using System;/// <summary>/// Provides methods to compute the greatest common divisor (GCD) of two non-negative integers using the Euclidean Algorithm./// </summary>public static class EuclideanAlgorithm{/// <summary>/// Computes the GCD of two integers using a recursive approach./// </summary>/// <param name="a">The first non-negative integer.</param>/// <param name="b">The second non-negative integer.</param>/// <returns>The GCD of the two integers.</returns>/// <exception cref="ArgumentOutOfRangeException">Thrown when either a or b is negative.</exception>public static int GetGCDRecursive(int a, int b){if (a < 0) throw new ArgumentOutOfRangeException(nameof(a), "Parameter 'a' must be non-negative.");if (b < 0) throw new ArgumentOutOfRangeException(nameof(b), "Parameter 'b' must be non-negative.");if (a == 0 && b == 0) return 0;if (b == 0) return Math.Abs(a);return GetGCDRecursive(b, a % b);}/// <summary>/// Computes the GCD of two integers using an iterative approach./// </summary>/// <param name="a">The first non-negative integer.</param>/// <param name="b">The second non-negative integer.</param>/// <returns>The GCD of the two integers.</returns>/// <exception cref="ArgumentOutOfRangeException">Thrown when either a or b is negative.</exception>public static int GetGCDIterative(int a, int b){if (a < 0) throw new ArgumentOutOfRangeException(nameof(a), "Parameter 'a' must be non-negative.");if (b < 0) throw new ArgumentOutOfRangeException(nameof(b), "Parameter 'b' must be non-negative.");if (a == 0 && b == 0) return 0;if (b == 0) return Math.Abs(a);while (b != 0){int temp = b;b = a % b;a = temp;}return Math.Abs(a);}